import { useState } from "react";
import { Box, Button, Menu, MenuItem } from "@mui/material";
import PaletteIcon from "@mui/icons-material/Palette";

const COLORS = [
  { name: "Red", value: "#e63946" },
  { name: "Blue", value: "#1d3557" },
  { name: "Green", value: "#2a9d8f" },
  { name: "Purple", value: "#6a0572" },
  { name: "Orange", value: "#e76f51" },
  { name: "Black", value: "#212529" },
];

const MangeLayout = () => {
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const [customColor, setCustomColor] = useState("#ffffff");

  const handleOpenMenu = (event: React.MouseEvent<HTMLButtonElement>) => {
    setAnchorEl(event.currentTarget);
  };

  const handleCloseMenu = () => {
    setAnchorEl(null);
  };

  const handleColorChange = (color: string) => {
    document.documentElement.style.setProperty("--primary-color", color);
    handleCloseMenu();
  };

  const handleCustomColorChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const color = event.target.value;
    setCustomColor(color);
    document.documentElement.style.setProperty("--primary-color", color);
  };

  return (
    <Box sx={{ position: "fixed", bottom: 20, right: 20 }}>
      <Button
        variant="contained"
        color="primary"
        startIcon={<PaletteIcon />}
        onClick={handleOpenMenu}
      >
        Change Color
      </Button>

      <Menu anchorEl={anchorEl} open={Boolean(anchorEl)} onClose={handleCloseMenu}>
        {COLORS.map((color) => (
          <MenuItem key={color.value} onClick={() => handleColorChange(color.value)}>
            <Box
              sx={{
                width: 20,
                height: 20,
                backgroundColor: color.value,
                borderRadius: "50%",
                display: "inline-block",
                marginRight: 1,
              }}
            />
            {color.name}
          </MenuItem>
        ))}
        <MenuItem>
          <input type="color" value={customColor} onChange={handleCustomColorChange} />
          Custom
        </MenuItem>
      </Menu>
    </Box>
  );
};

export default MangeLayout;
